// Re-run after editing workbench-sandbox.js. Both generated files are committed,
// so loading the extension itself still requires no build step.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'../extension'),source=fs.readFileSync(root+'/workbench-sandbox.js','utf8');
if(/<\/script/i.test(source))throw Error('The bootstrap must not contain an HTML closing script tag.');
const hash=crypto.createHash('sha256').update(source).digest('base64');
const policy=`default-src 'none'; script-src 'sha256-${hash}' 'unsafe-eval' blob:; worker-src blob:; connect-src blob:; child-src 'none';`;
fs.writeFileSync(root+'/workbench-sandbox.html',`<!doctype html>\n<!-- Generated by tests/sync-workbench-sandbox.cjs -->\n<html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="${policy}"><title>Isoleret programkørsel</title></head><body><script>${source}</script></body></html>\n`);
const manifest=JSON.parse(fs.readFileSync(root+'/manifest.json','utf8'));
manifest.content_security_policy.sandbox='sandbox allow-scripts; '+policy;
fs.writeFileSync(root+'/manifest.json',JSON.stringify(manifest,null,2)+'\n');
console.log('Sandbox bootstrap and matching CSP hashes updated.');
